contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address _vader, address _usdv, address _vault, address recipient, uint amount, uint oldProposalID, uint newProposalID) public {
        require(_vader != address(0) && _usdv != address(0) && _vault != address(0), "zero addresses");

        c.init(_vader, _usdv, _vault);

        // Create a GRANT proposal to be oldProposalID and another to be newProposalID.
        c.newGrantProposal(recipient, amount);
        c.newGrantProposal(recipient, amount);

        // Drive oldProposalID into finalising state.
        c.voteProposal(oldProposalID);

        // Attempt the cancel; the property only concerns the success path.
        bool reverted;
        try c.cancelProposal(oldProposalID, newProposalID) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If cancelProposal succeeded, mapPID_votes[oldProposalID] must be exactly 0.
        assert(reverted || c.mapPID_votes(oldProposalID) == 0);
    }

    receive() external payable {}
}
